  if (!fs.existsSync(stateDir)) {
    fs.mkdirSync(stateDir, { recursive: true });
  }
  fs.writeFileSync(stateFile, JSON.stringify(state, null, 2));
} catch (e) {
  console.error('Error writing thinking state:', e.message);
  process.exit(1);
}

// Display result
