console.log('   Deep Thinking: ' + (state.deepThinkingToggle ? '✅ ON' : '❌ OFF'));

const activeMode = state.deepThinkingToggle ? 'Deep Thinking' : 
                  state.thinkingToggle ? 'Extended Thinking' : 'Normal';
console.log('   Active Mode: ' + activeMode);
